<template><button class="btn-primary" @click="open=true">Создать тариф</button><BottomSheet :open="open" title="Новый тариф" @close="open=false"><form @submit.prevent="save" class="space-y-3"><label class="label">Название<input class="field" v-model.trim="form.title" required maxlength="200"></label><label class="label">Группа<select class="field" v-model="form.groupId" required><option value="" disabled>Выберите группу</option><option v-for="g in groups().filter(x=>x.is_active)" :key="g.id" :value="g.id">{{g.title}}</option></select></label><label class="label">Количество занятий<input class="field" type="number" min="1" max="1000" step="1" v-model.number="form.lessons" required></label><label class="label">Срок действия, дней<input class="field" type="number" min="1" max="3650" step="1" v-model.number="form.days" required></label><label class="label">Цена, ₽<input class="field" type="number" min="0.01" max="1000000" step="0.01" v-model.number="form.price" required></label><button class="btn-primary" :disabled="busy">Сохранить тариф</button></form></BottomSheet></template>
<script setup lang="ts">
import {reactive,ref} from 'vue';import BottomSheet from './BottomSheet.vue';import {useDemo} from '../shared/use-demo';const {groups,createTariff}=useDemo();const open=ref(false),busy=ref(false);const form=reactive({title:'',groupId:'',lessons:4,days:30,price:0});async function save(){if(busy.value)return;busy.value=true;try{await createTariff(form);open.value=false;form.title='';}finally{busy.value=false;}}
</script>
